"use client";
import { useMemo, useState } from "react";
const rows=[{date:"2026-09-14",receipt:"REC-00000001",amount:15000,payment:"cash",status:"completed"},{date:"2026-09-13",receipt:"REC-00000002",amount:27500,payment:"transfer",status:"completed"}];
export default function TransactionsPage(){const [q,setQ]=useState("");const [status,setStatus]=useState("all");const [payment,setPayment]=useState("all");const filtered=useMemo(()=>rows.filter(r=>(r.receipt.toLowerCase().includes(q.toLowerCase()))&&(status==="all"||r.status===status)&&(payment==="all"||r.payment===payment)),[q,status,payment]);return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><h1 className="text-2xl font-semibold">Transactions</h1><div className="mt-6 grid gap-3 md:grid-cols-3"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by receipt number..." className="field"/><select value={status} onChange={e=>setStatus(e.target.value)} className="field"><option value="all">All statuses</option><option value="completed">Completed</option></select><select value={payment} onChange={e=>setPayment(e.target.value)} className="field"><option value="all">All payment methods</option><option value="cash">Cash</option><option value="transfer">Transfer</option><option value="pos">POS</option></select></div><div className="mt-6 overflow-x-auto rounded-2xl border border-white/10 bg-[#151515] p-5"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{["DATE","RECEIPT","AMOUNT","PAYMENT","STATUS","ACTION"].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{filtered.map(r=><tr key={r.receipt} className="border-t border-white/5"><td className="px-3 py-4">{r.date}</td><td className="px-3 py-4">{r.receipt}</td><td className="px-3 py-4">₦{r.amount.toLocaleString()}</td><td className="px-3 py-4 capitalize">{r.payment}</td><td className="px-3 py-4"><span className="rounded-full bg-green-500/10 px-2 py-1 text-xs text-green-400">{r.status}</span></td><td className="px-3 py-4"><button className="text-red-400">Cancel</button></td></tr>)}</tbody></table></div></div></main>}
